package com.ejemplo.alquileres.service;
import com.ejemplo.alquileres.exception.NegocioException; import com.ejemplo.alquileres.model.*; import com.ejemplo.alquileres.repository.*;
import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*;
@Service @RequiredArgsConstructor public class InmuebleService {
 private final InmuebleRepository repository; private final TipoInmuebleRepository tipos; private final PropietarioRepository propietarios; private final SecuenciaService secuencias; private final Permisos permisos; private final Clock clock;
 public Page<Inmueble> listar(String texto,EstadoInmueble estado,Long tipoId,int pagina,int tamano){return repository.buscar(texto==null?"":texto.trim(),estado,tipoId,PageRequest.of(Math.max(0,pagina),tamano,Sort.by("codigo")));}
 @Transactional public String proximoCodigo(){return secuencias.formatear("INM-",secuencias.siguiente("INMUEBLE"),4);}
 @Transactional public Inmueble guardar(Inmueble a){permisos.exigirGestion();boolean nueva=a.getId()==null; if(a.getEstado()==EstadoInmueble.ALQUILADO)throw new NegocioException("El estado ALQUILADO solo puede establecerse desde un contrato"); Inmueble i=nueva?new Inmueble():repository.findById(a.getId()).orElseThrow(()->new NegocioException("El inmueble no existe"));if(!nueva&&i.getEstado()==EstadoInmueble.ALQUILADO&&a.getEstado()!=EstadoInmueble.ALQUILADO)throw new NegocioException("No se puede cambiar el estado de un inmueble alquilado manualmente");String codigo=(a.getCodigo()==null||a.getCodigo().isBlank())?proximoCodigo():a.getCodigo().trim().toUpperCase();if(nueva?repository.existsByCodigoIgnoreCase(codigo):repository.existsByCodigoIgnoreCaseAndIdNot(codigo,a.getId()))throw new NegocioException("Ya existe un inmueble con ese código");copiar(a,i);i.setCodigo(codigo);i.setTipo(a.getTipo()==null?null:tipos.findById(a.getTipo().getId()).orElseThrow(()->new NegocioException("El tipo no existe")));i.setPropietario(a.getPropietario()==null?null:propietarios.findById(a.getPropietario().getId()).orElseThrow(()->new NegocioException("El propietario no existe")));if(nueva)i.setFechaRegistro(LocalDate.now(clock));return repository.save(i);}
 private void copiar(Inmueble a,Inmueble i){i.setNombre(a.getNombre().trim());i.setDireccion(vacio(a.getDireccion()));i.setReferencia(vacio(a.getReferencia()));i.setDistrito(vacio(a.getDistrito()));i.setProvincia(vacio(a.getProvincia()));i.setDepartamento(vacio(a.getDepartamento()));i.setPiso(vacio(a.getPiso()));i.setAreaM2(escalar(a.getAreaM2()));i.setDormitorios(cero(a.getDormitorios()));i.setBanos(cero(a.getBanos()));i.setEstacionamientos(cero(a.getEstacionamientos()));i.setAmoblado(a.isAmoblado());i.setRentaReferencial(escalar(a.getRentaReferencial()));i.setEstado(a.getEstado()==null?EstadoInmueble.DISPONIBLE:a.getEstado());i.setServiciosIncluidos(vacio(a.getServiciosIncluidos()));i.setDescripcion(vacio(a.getDescripcion()));}
 private static int cero(Integer v){return v==null?0:v;} private static BigDecimal escalar(BigDecimal v){return v==null?null:v.setScale(2,RoundingMode.HALF_UP);} private static String vacio(String v){return v==null||v.isBlank()?null:v.trim();}
}
